package uk.ac.ravensbourne.casevault.service;
import java.util.UUID; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import uk.ac.ravensbourne.casevault.audit.AuditService; import uk.ac.ravensbourne.casevault.domain.*; import uk.ac.ravensbourne.casevault.repository.*; import uk.ac.ravensbourne.casevault.security.UserPrincipal; import uk.ac.ravensbourne.casevault.web.dto.CreateCaseRequest;
@Service public class CaseManagementService { private final OrganisationRepository orgs; private final UserAccountRepository users; private final CaseRepository cases; private final AccessPolicy policy; private final InputNormalizer input; private final AuditService audit; public CaseManagementService(OrganisationRepository o,UserAccountRepository u,CaseRepository c,AccessPolicy p,InputNormalizer i,AuditService a){orgs=o;users=u;cases=c;policy=p;input=i;audit=a;} @Transactional public CaseRecord create(UserPrincipal p,CreateCaseRequest request){if(!policy.canCreateCase(p))throw new CaseNotFoundException();var org=orgs.findById(p.organisationId()).orElseThrow(CaseNotFoundException::new);var user=users.findById(p.id()).orElseThrow(CaseNotFoundException::new);var result=cases.save(new CaseRecord(UUID.randomUUID(),org,input.title(request.title()),input.text(request.description()),request.category(),request.severity(),user));audit.record(p,"CASE_CREATED","CASE",result.getId(),"case-created");return result;} }
